"""Parse test result files generated by pytest-json-report and pytest-cov.

Produces a single dashboard-ready summary JSON file.
All figures come from actual test execution output — never estimated.
"""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from pathlib import Path

# ---------------------------------------------------------------------------
# Data classes
# ---------------------------------------------------------------------------

@dataclass
class TestCaseSummary:
    """Summary for one individual test."""
    node_id: str
    outcome: str          # passed | failed | error | skipped
    duration: float       # seconds
    category: str         # derived from file path
    failure_message: str  # empty string on pass


@dataclass
class SuiteSummary:
    """Aggregated results for one test category / file."""
    name: str
    total: int
    passed: int
    failed: int
    skipped: int
    errors: int
    duration: float
    pass_rate: float


@dataclass
class CoverageModule:
    """Coverage data for one application module."""
    name: str
    stmts: int
    miss: int
    cover: int   # integer percentage


@dataclass
class DashboardData:
    """Complete data structure written to summary.json for the dashboard."""
    timestamp: str
    duration: float
    total: int
    passed: int
    failed: int
    skipped: int
    errors: int
    pass_rate: float
    coverage_total: int
    coverage_scope: str
    suites: list[SuiteSummary]
    failed_tests: list[TestCaseSummary]
    all_tests: list[TestCaseSummary]
    coverage_modules: list[CoverageModule]


# ---------------------------------------------------------------------------
# Parsing helpers
# ---------------------------------------------------------------------------

def _derive_category(node_id: str) -> str:
    """Map a test node_id to a human-readable category."""
    p = node_id.lower()
    if "integration" in p:
        return "Integration"
    if "unit" in p:
        return "Unit"
    if "regression" in p:
        return "Regression"
    if "security" in p:
        return "Security"
    return "Other"


def _parse_test_results(path: Path) -> list[TestCaseSummary]:
    """Parse pytest-json-report output into TestCaseSummary objects."""
    if not path.exists():
        return []

    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)

    results: list[TestCaseSummary] = []
    for test in data.get("tests", []):
        outcome = test.get("outcome", "unknown")
        duration = test.get("call", {}).get("duration", 0.0) if test.get("call") else 0.0

        # Collect failure message
        failure_msg = ""
        if outcome in ("failed", "error"):
            for phase in ("setup", "call", "teardown"):
                phase_data = test.get(phase) or {}
                if phase_data.get("longrepr"):
                    failure_msg = str(phase_data["longrepr"])[:500]
                    break

        results.append(
            TestCaseSummary(
                node_id=test.get("nodeid", ""),
                outcome=outcome,
                duration=round(duration, 4),
                category=_derive_category(test.get("nodeid", "")),
                failure_message=failure_msg,
            )
        )
    return results


def _aggregate_suites(tests: list[TestCaseSummary]) -> list[SuiteSummary]:
    """Group tests by category and compute per-suite statistics."""
    suites: dict[str, dict] = {}
    for t in tests:
        cat = t.category
        if cat not in suites:
            suites[cat] = {
                "name": cat, "passed": 0, "failed": 0,
                "skipped": 0, "errors": 0, "duration": 0.0,
            }
        suites[cat]["duration"] += t.duration
        if t.outcome == "passed":
            suites[cat]["passed"] += 1
        elif t.outcome == "failed":
            suites[cat]["failed"] += 1
        elif t.outcome == "skipped":
            suites[cat]["skipped"] += 1
        elif t.outcome in ("error", "xfailed", "xpassed"):
            suites[cat]["errors"] += 1

    result = []
    for s in suites.values():
        total = s["passed"] + s["failed"] + s["skipped"] + s["errors"]
        pass_rate = round(s["passed"] / total * 100, 1) if total > 0 else 0.0
        result.append(
            SuiteSummary(
                name=s["name"],
                total=total,
                passed=s["passed"],
                failed=s["failed"],
                skipped=s["skipped"],
                errors=s["errors"],
                duration=round(s["duration"], 2),
                pass_rate=pass_rate,
            )
        )
    return sorted(result, key=lambda x: x.name)


def _parse_coverage(path: Path) -> tuple[int, list[CoverageModule]]:
    """Parse pytest-cov JSON output. Returns (total_pct, modules)."""
    if not path.exists():
        return 0, []

    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)

    totals = data.get("totals", {})
    total_pct = int(round(totals.get("percent_covered", 0)))

    modules: list[CoverageModule] = []
    for filename, file_data in data.get("files", {}).items():
        summary = file_data.get("summary", {})
        stmts = summary.get("num_statements", 0)
        miss = summary.get("missing_lines", 0)
        cover_pct = int(round(summary.get("percent_covered", 0)))
        # Use a short relative name
        short_name = filename.replace("\\", "/")
        if "app/" in short_name:
            short_name = short_name[short_name.index("app/"):]
        modules.append(CoverageModule(name=short_name, stmts=stmts, miss=miss, cover=cover_pct))

    return total_pct, sorted(modules, key=lambda m: m.name)


# ---------------------------------------------------------------------------
# Public interface
# ---------------------------------------------------------------------------

def generate_dashboard_summary(
    results_path: Path,
    coverage_path: Path,
    output_path: Path,
    timestamp: str,
) -> DashboardData:
    """Parse test and coverage reports and write a dashboard summary JSON.

    Parameters
    ----------
    results_path:
        Path to the pytest-json-report output file (test_results.json).
    coverage_path:
        Path to the pytest-cov JSON output file (coverage.json).
    output_path:
        Destination for the merged summary file (summary.json).
    timestamp:
        ISO 8601 string representing when the run completed.

    Returns
    -------
    DashboardData
        The same data that was written to ``output_path``.
    """
    tests = _parse_test_results(results_path)
    coverage_total, coverage_modules = _parse_coverage(coverage_path)

    total = len(tests)
    passed = sum(1 for t in tests if t.outcome == "passed")
    failed = sum(1 for t in tests if t.outcome == "failed")
    skipped = sum(1 for t in tests if t.outcome == "skipped")
    errors = sum(1 for t in tests if t.outcome in ("error",))
    duration = round(sum(t.duration for t in tests), 2)
    pass_rate = round(passed / total * 100, 1) if total > 0 else 0.0

    suites = _aggregate_suites(tests)
    failed_tests = [t for t in tests if t.outcome in ("failed", "error")]

    dashboard = DashboardData(
        timestamp=timestamp,
        duration=duration,
        total=total,
        passed=passed,
        failed=failed,
        skipped=skipped,
        errors=errors,
        pass_rate=pass_rate,
        coverage_total=coverage_total,
        coverage_scope="app/ (application source only)",
        suites=suites,
        failed_tests=failed_tests,
        all_tests=tests,
        coverage_modules=coverage_modules,
    )

    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as fh:
        json.dump(asdict(dashboard), fh, indent=2, default=str)

    return dashboard
